<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import plan from '@/data/assessmentPlan.json'
import { usePmisStore } from '@/stores/pmis'
import { validatePdmLinks, type PdmLink } from '@/lib/pdmScenario'
const props=defineProps<{basis:string}>(), pm=usePmisStore()
const emit=defineEmits<{preview:[links:PdmLink[]|null]}>()
const links=ref<PdmLink[]>([]), enabled=ref(false), message=ref(''), blocked=ref(false)
const source=ref(''), target=ref(''), relation=ref<PdmLink['relation']>('FS'), lag=ref(0), reason=ref('')
const history=ref<{at:string;actor:string;reason:string;before:PdmLink[];after:PdmLink[]}[]>([])
const tasks=computed(()=>plan.tasks.filter(t=>t.basis===props.basis))
const key=()=>`pacificpower-pdm-scenario-v1:${pm.project}:${props.basis}`
const baseline=()=>plan.annotatedDependencies.filter(e=>tasks.value.some(t=>t.code===e.source)&&tasks.value.some(t=>t.code===e.target)).map(e=>({...e,relation:e.relation as PdmLink['relation'],lag:0}))
watch(()=>[props.basis,pm.project],()=>{enabled.value=false;emit('preview',null);blocked.value=false;message.value='';links.value=baseline();history.value=[];source.value='';target.value='';reason.value='';try{const raw=localStorage.getItem(key());if(raw){const value=JSON.parse(raw);if(value.schema!==1||!Array.isArray(value.links)||!Array.isArray(value.history))throw new Error();validatePdmLinks(value.links,tasks.value.map(t=>t.code));for(const h of value.history){if(typeof h.actor!=='string'||typeof h.at!=='string'||typeof h.reason!=='string'||!Array.isArray(h.before)||!Array.isArray(h.after))throw new Error();validatePdmLinks(h.before,tasks.value.map(t=>t.code));validatePdmLinks(h.after,tasks.value.map(t=>t.code))}links.value=value.links;history.value=value.history}}catch{blocked.value=true;message.value='情境資料無法讀取，已停止覆寫；請先保留原瀏覽器資料。'}},{immediate:true})
function toggle(){emit('preview',enabled.value?links.value:null)}
function change(next:PdmLink[]){try{if(blocked.value)throw new Error('資料讀取異常，無法覆寫');if(!pm.actor.trim()||!reason.value.trim())throw new Error('請填寫操作人與調整原因');validatePdmLinks(next,tasks.value.map(t=>t.code));if(JSON.stringify(next)===JSON.stringify(links.value))throw new Error('尚未變更關係');const entry={at:new Date().toISOString(),actor:pm.actor.trim(),reason:reason.value.trim(),before:links.value,after:next};const updated=[entry,...history.value];localStorage.setItem(key(),JSON.stringify({schema:1,links:next,history:updated}));links.value=next;history.value=updated;reason.value='';enabled.value=true;emit('preview',links.value);message.value='情境已保存，圖表已切換至試編關係；未改動原基準或工作日期。'}catch(e){message.value=e instanceof Error?e.message:'儲存失敗'}}
function upsert(){const item={source:source.value,target:target.value,relation:relation.value,lag:lag.value};const rest=links.value.filter(e=>e.source!==item.source||e.target!==item.target);change([...rest,item])}
function edit(e:PdmLink){source.value=e.source;target.value=e.target;relation.value=e.relation;lag.value=e.lag}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify({schema:1,project:pm.project,basis:props.basis,source:plan.source,scope:'未核定排程情境；原文件未提供延遲量，初始值 0 僅供試編',links:links.value,history:history.value},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`pdm-scenario-${props.basis}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><details class="scenario"><summary>PDM 排程情境試編（未核定）</summary><p>情境單獨存於此瀏覽器，不納入既有 PMIS 備份，請使用本區匯出。原文件無延遲量，初始 0 為試編假設。只檢查關係，不重排日期或計算要徑。</p><label class="check"><input type="checkbox" v-model="enabled" @change="toggle" />在上方 PDM 圖預覽試編關係</label><label>操作人<input v-model="pm.actor" placeholder="具名操作人" /></label><div class="fields"><label>前置工作<select v-model="source"><option value="">選擇工作</option><option v-for="t in tasks" :key="t.code" :value="t.code">{{t.code}} {{t.name}}</option></select></label><label>後續工作<select v-model="target"><option value="">選擇工作</option><option v-for="t in tasks" :key="t.code" :value="t.code">{{t.code}} {{t.name}}</option></select></label><label>關係<select v-model="relation"><option>FS</option><option>SS</option><option>FF</option><option>SF</option></select></label><label>延遲工作日<input v-model.number="lag" type="number" min="0" max="365" step="1" /></label></div><p>FF：前置完成後才能完成後續；SF：前置開始後才能完成後續。本版不支援負延遲（提前量）。</p><label>調整原因<textarea v-model="reason" placeholder="新增、調整、移除或恢復基準的原因" /></label><div class="actions"><button @click="upsert" :disabled="blocked">新增／更新同一前後關係</button><button @click="change(baseline())" :disabled="blocked">將情境恢復為原關係</button><button @click="download">匯出情境與異動紀錄</button></div><p role="status">{{message}}</p><div class="table"><table><thead><tr><th>前置 → 後續</th><th>關係／延遲</th><th>操作</th></tr></thead><tbody><tr v-for="e in links" :key="`${e.source}:${e.target}`"><td>{{e.source}} → {{e.target}}</td><td>{{e.relation}} +{{e.lag}} 工作日</td><td><button @click="edit(e)">載入編輯</button><button @click="change(links.filter(x=>x!==e))" :disabled="blocked">移除</button></td></tr></tbody></table></div><details><summary>情境異動紀錄（{{history.length}}）</summary><article v-for="(h,i) in history" :key="i"><b>{{h.actor}} · {{h.at}}</b><p>{{h.reason}} · {{h.before.length}} → {{h.after.length}} 條關係</p></article></details></details></template>
<style scoped>
.scenario{padding:16px;border:1px solid var(--line);margin:20px 0}summary{cursor:pointer;color:#7bd7ff}label{display:flex;flex-direction:column;gap:5px;margin:10px 0;max-width:100%}.check{flex-direction:row}.fields,.actions{display:flex;flex-wrap:wrap;gap:10px}input,select,textarea,button{font:inherit;color:var(--text);background:var(--panel-solid);border:1px solid var(--line);padding:8px;border-radius:6px;max-width:100%}button{cursor:pointer}button:disabled{opacity:.5}textarea{min-height:70px}.table{max-height:320px;overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:8px;text-align:left;border-bottom:1px solid var(--line)}p{overflow-wrap:anywhere}
</style>
